/// WHAT THE DISPLAY PATH HOLDS THAT THE KERNEL CHARGES NOBODY FOR.
///
/// A PRESENTABLE IMAGE IS A MEMORYOBJECT and is charged to the Domain that created it, which under
/// this contract is the client's. EVERYTHING ELSE here - the surface record, its queue slots, its
/// pending-present list, its event stream and its place in the service's wait vector - is service
/// heap and a service wait set, charged to nobody. Those are exactly what an adversarial client can
/// multiply, so each is reported with the bound it is held to.
///
/// OBSERVATION AND NEVER ENFORCEMENT. Reading these changes nothing; the bounds are enforced where
/// the structures are allocated, and a reader that found a count at its bound has learned that a
/// client is being refused rather than caused it to be.
///
/// AND NEVER IMAGE CONTENTS. There is no field here from which a pixel can be recovered: what a
/// surface SHOWS is not an observability question.
#[derive(Clone, Debug, PartialEq)]
pub struct DisplayResources {
	/// Live surfaces across every connection, and the service-wide ceiling.
	pub surfaces: u64,
	pub surface_bound: u64,
	/// Queue slots across every surface, supplied or not, and the most one surface may negotiate.
	pub present_images: u64,
	pub image_bound: u64,
	/// Accepted presents not yet settled, and the most one surface may have outstanding.
	pub queued_presents: u64,
	pub present_bound: u64,
	/// Damage rectangles this service RETAINS, and the most one present may carry.
	///
	/// THE LIVE COUNT IS ZERO IN THIS IMPLEMENTATION AND THAT IS THE POINT: damage lives for the
	/// duration of the present call that carried it and is never stored, so there is nothing here
	/// for a client to multiply. An implementation that deferred presents would retain them, and
	/// this is the field it would have to report.
	pub damage_entries: u64,
	pub damage_bound: u64,
	/// Handles this service's one progress loop waits on, and the kernel's ceiling on a wait set.
	pub waiters: u64,
	pub waiter_bound: u64,
	/// How many times the display path has been RESET: a scanout adopted after the previous one
	/// went away. A machine whose GPU driver keeps restarting shows it here.
	pub resets: u64,
	/// Whether this service currently has NO scanout at all - the fault state, which is different
	/// from a reset that succeeded.
	pub faulted: bool,
}

